/* data.js — static content. Chapters come from js/data-syllabus.js (generated by
 * tools/build.py from data/syllabus-2027.json, data/id-map.json and data/estimates.json).
 * Edit those data/ files and rebuild, don't hand-edit chapters here.
 *
 * Chapter weightage / priority / difficulty / hours are PLANNING ESTIMATES — see
 * data/estimates.json and each chapter's `est` / `default` flags. Adjust with your
 * teacher's advice, then edit data/estimates.json and rebuild.
 */
(function (S) {
  'use strict';
  const D = (S.data = {});

  D.SUBJECTS = {
    phy: { id: 'phy', name: 'Physics', short: 'Physics', legacy: 'physics' },
    chem: { id: 'chem', name: 'Chemistry', short: 'Chemistry', legacy: 'chemistry' },
    mth: { id: 'mth', name: 'Mathematics', short: 'Maths', legacy: 'maths' },
    cs: { id: 'cs', name: 'Computer Science', short: 'CS', legacy: 'cs' },
  };
  D.SUBJECT_ORDER = ['phy', 'chem', 'mth', 'cs'];
  // v1: Computer Science is "Coming soon". Its topic lists are unverified drafts, so Subjects shows no chapter list for it and
  // Continue, Today and Practice never pick a CS item. The CS data stays in the repo untouched.
  D.COMING_SOON = { cs: true };

  D.CHAPTERS = [];
  D.CH = {};
  D.BY_SUBJECT = { phy: [], chem: [], mth: [], cs: [] };
  D.SUBJECT_ORDER.forEach((s) => {
    let idx = 0;
    (S.SYLLABUS || []).filter((c) => c.subj === s).forEach((c) => {
      const est = S.ESTIMATES[c.id];
      if (!est) throw new Error('data.js: no estimate for chapter "' + c.id + '"');
      const ch = {
        id: c.id,
        subj: s,
        idx: idx++,
        name: c.name,
        std: c.std,
        tb: c.tb,
        part: c.part,
        paper: c.paper,
        pages: c.pages, // printed page range in a non-Balbharati book, or null
        book: c.book,
        board: c.board,
        cet: c.cet, // in the MHT-CET syllabus (bool)
        jee: c.jee, // yes | no | partial | verify
        w: est.w,
        cetPri: est.cetPri, // 0-3 planning priority for Study Next, not the same as `cet`
        jeePri: est.jeePri, // 0-3 planning priority for Study Next, not the same as `jee`
        diff: est.diff,
        hours: est.hours,
        deps: est.deps,
        hy: est.hy,
        est: !!est.est,
        estDefault: !!est.default,
        seedDone: c.status === 'done', // she reported this chapter finished when the syllabus was captured
      };
      D.CHAPTERS.push(ch);
      D.CH[ch.id] = ch;
      D.BY_SUBJECT[s].push(ch);
    });
  });

  D.STATUS = [
    { id: 'todo', label: 'Not started', credit: 0 },
    { id: 'learning', label: 'Learning', credit: 0.4 },
    { id: 'done', label: 'Done', credit: 0.85 },
    { id: 'mastered', label: 'Mastered', credit: 1 },
  ];
  D.PRIORITY = ['—', 'Low', 'Medium', 'High'];
  D.DIFFICULTY = ['', 'Easy', 'Moderate', 'Hard', 'Very hard'];

  D.INTERVALS = [1, 3, 7, 15, 30]; // spaced-repetition gaps in days

  D.TIMETABLE = [
    { id: 's1', from: '06:30', to: '08:30', label: 'Mathematics: new concept + theory', subj: 'mth' },
    { id: 's2', from: '09:00', to: '11:00', label: 'Physics classroom: concept + derivation', subj: 'phy' },
    { id: 's3', from: '11:15', to: '13:15', label: 'Chemistry classroom: theory + notes', subj: 'chem' },
    { id: 's4', from: '14:15', to: '16:00', label: 'MCQ practice (JEE + CET)', subj: 'mcq' },
    { id: 's5', from: '16:30', to: '18:30', label: 'PYQs / numericals', subj: 'pyq' },
    { id: 's6', from: '19:15', to: '20:30', label: 'Formula revision + error notebook', subj: 'rev' },
  ];

  D.HABITS = [
    { id: 'h-hours', label: 'Completed 10 study hours' },
    { id: 'h-mth', label: 'Mathematics completed' },
    { id: 'h-phy', label: 'Physics completed' },
    { id: 'h-chem', label: 'Chemistry completed' },
    { id: 'h-mcq', label: 'Solved 90 MCQs' },
    { id: 'h-pyq', label: 'PYQ practice completed' },
    { id: 'h-formula', label: 'Formula revision done' },
    { id: 'h-sleep', label: 'Slept 7+ hours' },
  ];

  D.ERROR_REASONS = [
    'Concept not clear',
    'Formula forgot',
    'Calculation error',
    'Silly mistake',
    'Time pressure',
    'Question misread',
  ];

  D.QUOTES = [
    'Discipline beats motivation every single day.',
    "Your CET rank is built by today's study session.",
    'Small daily improvements become extraordinary results.',
    'Consistency for 90 days changes your engineering future.',
    'Master concepts, then master MCQs.',
    'Revision is where marks are actually scored.',
    "Don't chase hours. Chase understanding.",
    'Every PYQ solved is one question less to fear.',
    'Trust the timetable. Ignore temporary emotions.',
    'A mistake written in the Error Notebook is a mark saved in the exam.',
    'Rest is part of the plan. A sharp mind scores more than a tired one.',
  ];

  D.MOCKS = {
    cet: { label: 'MHT-CET mock', short: 'CET', count: 12, total: 200, mins: 180 },
    jee: { label: 'JEE Main mock', short: 'JEE', count: 8, total: 300, mins: 180 },
    phy: { label: 'Physics test', short: 'Physics', count: 0, total: 50, mins: 60 },
    chem: { label: 'Chemistry test', short: 'Chemistry', count: 0, total: 50, mins: 60 },
    mth: { label: 'Maths test', short: 'Maths', count: 0, total: 50, mins: 60 },
    // Test Center practice attempts spanning several chapters/subjects (custom mix, Quick 10,
    // retry). Summary rows only; total and time come from each attempt.
    mix: { label: 'Practice test', short: 'Practice', count: 0, total: 0, mins: 0 },
  };

  D.PHASES = {
    A: 'Phase A',
    B: 'Phase B',
    C: 'Gap sweep',
    D: 'Repair + mocks',
    REV: 'Revision',
    MOCK: 'Mock',
    TARGET: 'Target',
  };

  /* ---- Planner: turn RAW_PLAN rows into day objects ---- */

  // First matching rule wins. Text is matched case-insensitively against the topic.
  // Targets are the NEW (Phase 1) chapter ids. Where an old chapter split across two new
  // ones (Electrostatics, Modern Physics, Definite Integration), the more specific rule
  // is listed first.
  const TOPIC_RULES = {
    mth: [
      [/matric/, 'mth-12-02'], [/determinant/, 'mth-12-02'],
      [/inverse trig/, 'mth-12-03'], [/trigonometric eq/, 'mth-12-03'], [/trigonometric func/, 'mth-12-03'],
      [/height/, null],
      [/pair of straight|straight lines/, 'mth-12-04'], [/linear programming/, 'mth-12-07'],
      [/logic/, 'mth-12-01'], [/circle/, 'mth-11-03'], [/ellipse/, 'mth-11-04'],
      [/hyperbola/, 'mth-11-04'], [/conic/, 'mth-11-04'], [/vector|dot product|cross product/, 'mth-12-05'],
      [/3d|direction cosine/, 'mth-12-06'],
      [/area under/, 'mth-12-12'], [/definite/, 'mth-12-11'],
      [/integration|substitution|properties of integrals/, 'mth-12-10'],
      [/differential eq|variables separable|linear de|de test/, 'mth-12-13'],
      [/binomial/, 'mth-12-15'], [/probab|bayes|random variable/, 'mth-11-05'],
      [/permutation|combination|p&c/, 'mth-11-07'], [/sequence|series/, null],
      [/complex|argand/, 'mth-11-06'], [/statistic|mean median|variance/, null],
      [/aod/, 'mth-12-09'], [/continuity|differentiability/, 'mth-11-10'],
      [/differentiation|higher derivatives/, 'mth-12-08'], [/limit/, 'mth-11-09'], [/function/, 'mth-11-08'],
    ],
    phy: [
      [/calorimetry/, 'phy-11-06'], [/thermodynamics/, 'phy-12-04'], [/thermal|heat transfer/, 'phy-11-06'],
      [/kinetic theory/, 'phy-12-03'], [/kinematics|units/, 'phy-11-03'], [/laws of motion/, 'phy-11-04'],
      [/work, power/, 'phy-11-04'], [/rotational/, 'phy-12-01'], [/gravitation/, 'phy-11-05'],
      [/fluid/, 'phy-12-02'], [/semiconductor/, 'phy-12-16'],
      [/electrostatic|electric field|electric potential|capacit/, 'phy-12-08'],
      [/magnet|moving charge|circular motion in b|biot|ampere/, 'phy-12-10'],
      [/current|kirchhoff|cells|wheatstone|potentiometer/, 'phy-12-09'],
      [/\bemi\b|faraday|lenz|inductance/, 'phy-12-12'], [/^ac /, 'phy-12-13'],
      [/wave|young|diffraction|interference|polaris/, 'phy-12-07'],
      [/ray optics|reflection|refraction|optics|lens|prism/, 'phy-11-08'],
      [/bohr/, 'phy-12-15'], [/photoelectric|modern/, 'phy-12-14'],
    ],
    chem: [
      [/mole concept/, 'chem-11-01'], [/atomic/, 'chem-11-02'], [/bonding|vsepr|\bmot\b/, 'chem-11-03'],
      [/states of matter/, 'chem-11-06'], [/thermodynamics/, 'chem-12-04'],
      [/equilibrium|ionic|acid base/, 'chem-12-03'], [/redox/, 'chem-11-04'], [/hydrogen/, null],
      [/s-block/, 'chem-11-05'], [/solid state/, 'chem-12-01'], [/polymer/, 'chem-12-15'],
      [/environmental/, null], [/everyday/, 'chem-11-10'],
      [/solutions|colligative|electrolytes/, 'chem-12-02'], [/electrochem/, 'chem-12-05'],
      [/kinetics|rate law|order &/, 'chem-12-06'], [/surface|adsorption/, 'chem-11-07'],
      [/goc|inductive|resonance|hyperconjugation|acidity/, 'chem-11-08'], [/haloalkane|haloarene/, 'chem-12-10'],
      [/hydrocarbon|alkane/, 'chem-11-09'], [/alcohol|phenol|ether/, 'chem-12-11'],
      [/aldehyde|ketone|carboxylic|carbonyl/, 'chem-12-12'], [/amine/, 'chem-12-13'],
      [/biomolecule/, 'chem-12-14'], [/coordination/, 'chem-12-09'], [/d & f/, 'chem-12-08'],
      [/p block/, 'chem-12-07'],
    ],
  };
  D.mapTopic = (subj, text) => {
    const t = text.toLowerCase();
    const rules = TOPIC_RULES[subj] || [];
    for (let i = 0; i < rules.length; i++) if (rules[i][0].test(t)) return rules[i][1];
    return null;
  };

  // Three generic study passes per CS chapter (board-only, so no CET/JEE-style topic split
  // is meaningful — these are process steps, not syllabus content).
  const CS_PARTS = {};
  D.BY_SUBJECT.cs.forEach((c) => {
    CS_PARTS[c.id] = ['Theory + notes', 'Textbook exercises', 'Board questions'];
  });
  const MCQ_BY_DOW = { 1: 90, 2: 90, 3: 100, 4: 100, 5: 120, 6: 150, 0: 150 };

  D.PLAN = [];
  D.PLAN_BY_DATE = {};
  (function buildPlan() {
    const u = S.u;
    const raw = S.RAW_PLAN || [];
    const csDays = [];
    raw.forEach((r, i) => {
      const phase = r[1];
      if (phase !== 'MOCK' && phase !== 'REV' && phase !== 'TARGET' && u.dow(r[0]) !== 0) csDays.push(i);
    });
    const csParts = [];
    Object.keys(CS_PARTS).forEach((id) => CS_PARTS[id].forEach((p) => csParts.push({ id: id, text: p })));

    raw.forEach((r, i) => {
      const d = {
        i: i,
        n: i + 1,
        date: r[0],
        phase: r[1],
        m: { t: r[2], ch: D.mapTopic('mth', r[2]) },
        p: { t: r[3], ch: D.mapTopic('phy', r[3]) },
        c: { t: r[4], ch: D.mapTopic('chem', r[4]) },
        s: null,
        mcq: MCQ_BY_DOW[u.dow(r[0])],
      };
      const k = csDays.indexOf(i);
      if (k >= 0) {
        const part = csParts[Math.floor((k * csParts.length) / csDays.length)];
        d.s = { t: D.CH[part.id].name + ': ' + part.text, ch: part.id };
      }
      if (i > 0) {
        const prev = raw[i - 1];
        d.rev = 'Revise yesterday: ' + [prev[2], prev[3], prev[4]].join(' · ');
      } else d.rev = 'Skim your class notes';
      if (d.phase === 'MOCK') d.rev = 'Analyse the mock. Log every wrong question.';
      if (d.phase === 'REV') d.rev = 'Full revision block. Clear all due revisions.';
      D.PLAN.push(d);
      D.PLAN_BY_DATE[d.date] = d;
    });
    D.PLAN_START = raw.length ? raw[0][0] : null;
    D.PLAN_END = raw.length ? raw[raw.length - 1][0] : null;
  })();

  // Chapters that appear in no planner day (used by the "not in your plan" note).
  D.UNPLANNED = (function () {
    const seen = {};
    D.PLAN.forEach((d) => ['m', 'p', 'c', 's'].forEach((k) => d[k] && d[k].ch && (seen[d[k].ch] = 1)));
    return D.CHAPTERS.filter((c) => !seen[c.id]).map((c) => c.id);
  })();

  /* ---- Old-id remapping (Phase 1 chapter model change, store v2 -> v3) ---- */
  // S.ID_MAP (from js/data-syllabus.js) = { oldToNew, newToOld, orphans, legacyOrder }.
  // oldId -> new chapter id, or null if the old chapter has no Phase 1 equivalent.
  D.remapChapterId = (oldId) => {
    const m = S.ID_MAP && S.ID_MAP.oldToNew;
    return m && Object.prototype.hasOwnProperty.call(m, oldId) ? m[oldId] : null;
  };
  // Legacy v1 app chapter ids were "<subject>_<index>", index into the ORIGINAL (pre-Phase-1)
  // ROWS order for that subject. Returns the OLD chapter id (never a new one) or null.
  D.legacyOldId = (subjectKey, index) => {
    const legacyToShort = { physics: 'phy', chemistry: 'chem', maths: 'mth', cs: 'cs' };
    const s = legacyToShort[subjectKey];
    const order = S.ID_MAP && S.ID_MAP.legacyOrder && S.ID_MAP.legacyOrder[s];
    return (order && order[index]) || null;
  };
  // Convenience: legacy subject_index -> NEW chapter id (null if orphaned or unknown).
  D.legacyChapterId = (subjectKey, index) => {
    const oldId = D.legacyOldId(subjectKey, index);
    return oldId ? D.remapChapterId(oldId) : null;
  };
})((window.SOS = window.SOS || {}));
